'use strict';
/* 2.0 authoritative workspace UI. Shared task rows, forms, calendar and dashboard. */
const Studio = {sort:'due', picked:new Set(), snapshots:new Map(), owner:'', focus:null, timer:null, elapsed:0, runningAt:0, searchFiles:[], searchKey:'', searchError:'', searchLoading:false};
function studioMeta(){return data.studio||(data.studio={templates:[],filters:[],reviews:[]});}
function studioStamp(at){return new Date(at).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',dateStyle:'short',timeStyle:'short'});}
function studioContext(){return typeof currentUser!=='undefined'&&currentUser?currentUser.id:KEY;}
function studioSnapshot(){Studio.owner=studioContext();Studio.snapshots=new Map(data.projects.flatMap(p=>p.tasks.map(t=>[t.id,structuredClone(t)])));}
function studioWrite(fn){const before=structuredClone(data);try{if(typeof contentReadOnly!=='undefined'&&contentReadOnly)throw Error('Đây là bản chia sẻ chỉ xem.');fn();if(!valid(data))throw Error('Nội dung vượt giới hạn hoặc không hợp lệ.');if(save()===false)throw Error('Chưa lưu được. Dữ liệu trước thao tác được giữ.');return true;}catch(error){data=before;studioSnapshot();notify(error.message);return false;}}
const studioSaveBefore=save;
save=function(){
 if(Studio.owner!==studioContext())studioSnapshot();
 const backup=structuredClone(data);
 for(const p of data.projects)for(const t of [...p.tasks]){
  const old=Studio.snapshots.get(t.id),changes=old?zenTaskChanges(old,t):[{label:'Tạo công việc',before:'',after:t.title.slice(0,220)}];
  if(changes.length)t.history=[...(t.history||[]),...changes.map(c=>({id:uid(),at:Date.now(),label:c.label,before:c.before,after:c.after}))].slice(-80);
  if(old&&old.col!=='Done'&&t.col==='Done'&&['daily','weekly'].includes(t.recurrence)&&p.tasks.length<2000){
   const next=zenFreshTask(t,uid),step=t.recurrence==='daily'?1:7,base=t.due||today();next.due=zenShift(base<today()?today():base,step);next.recurrence=t.recurrence;next.id='repeat-'+t.id.slice(0,65)+'-'+next.due;if(p.tasks.some(x=>x.id===next.id))continue;
   const delta=Math.round((Date.parse(next.due)-Date.parse(base))/86400000);
   for(const k of ['start','end'])if(t[k])next[k]=zenShift(t[k].slice(0,10),delta)+t[k].slice(10);
   next.noteIds=[...(t.noteIds||[])];next.history=[{id:uid(),at:Date.now(),label:'Tạo kỳ lặp tiếp theo',before:'',after:next.due}];p.tasks.push(next);
  }
 }
 if(new TextEncoder().encode(JSON.stringify(data)).length>1850000){data=backup;notify('Dữ liệu vượt dung lượng đồng bộ. Hãy xuất bản sao và giảm nội dung trước khi lưu.');return false;}
 if(!valid(data)){data=backup;notify('Chưa lưu: dữ liệu không hợp lệ.');return false;}
 const result=studioSaveBefore();if(result===false){data=backup;return false;}studioSnapshot();studioSaveLabels();return result;
};
function studioSaveLabels(){const state=$('#save-state')?.dataset.sync||'local';document.querySelectorAll('[data-studio-saved]').forEach(el=>{if($('#editor')?.studioDirty&&$('#editor').contains(el)){el.textContent='Đang chỉnh sửa · chưa lưu';return;}el.textContent={saved:'Đã đồng bộ',pending:'Đã lưu trên máy · đang gửi',offline:'Đã lưu trên máy · chờ kết nối',error:'Cần xử lý · mở Cài đặt',local:'Đã lưu trên máy'}[state]||'Đã lưu trên máy';});}
const studioStatusBefore=syncStatus;
syncStatus=function(message,kind){
 const text=String(message||'');kind=kind||(/xung đột|từ chối|không hợp lệ|chưa lưu|không thể lưu|cần kiểm tra/i.test(text)?'error':/chờ kết nối|chờ mạng|mất mạng/i.test(text)?'offline':/đang đồng bộ|tiếp tục đồng bộ/i.test(text)?'pending':/đã đồng bộ|đã cập nhật/i.test(text)?'saved':'local');
 if(kind==='saved')try{localStorage.setItem(KEY+'-last-sync',String(Date.now()));}catch{}
 const names={saved:'Đã đồng bộ',pending:'Đang gửi',offline:'Đã lưu trên máy',local:'Đã lưu trên máy',error:'Cần xử lý'};
 studioStatusBefore(names[kind]||names.local,kind);const el=$('#save-state'),last=localStorage.getItem(KEY+'-last-sync');if(el){el.title=names[kind]+' · '+text+(last?' · Đồng bộ thành công gần nhất: '+studioStamp(Number(last)):' · Chưa có lần đồng bộ thành công trên thiết bị này');el.setAttribute('aria-label',el.title);el.tabIndex=0;}studioSaveLabels();
};
function studioDates(t){return '<dl class="studio-dates"><div><dt>Bắt đầu</dt><dd>'+esc(t.start?.replace('T',' ')||'Chưa đặt')+'</dd></div><div><dt>Kết thúc</dt><dd>'+esc(t.end?.replace('T',' ')||'Chưa đặt')+'</dd></div><div><dt>Hạn hoàn thành</dt><dd class="'+(t.due&&t.due<today()&&t.col!=='Done'?'studio-late':'')+'">'+esc(t.due||'Chưa đặt')+'</dd></div></dl>';}
function studioTaskRow(t,{select=false,focus=false}={}){const p=t.project||data.projects.find(p=>p.tasks.some(x=>x.id===t.id));if(!p)return '';return '<article class="studio-task-row">'+(select?'<label class="studio-select"><input type="checkbox" data-studio-pick="'+t.id+'" '+(Studio.picked.has(t.id)?'checked':'')+' aria-label="Chọn '+esc(t.title)+'"></label>':'')+'<button type="button" class="studio-task-open" data-task="'+t.id+'" data-pid="'+p.id+'"><strong>'+esc(t.title)+'</strong><small>'+esc(p.name)+' · '+esc(t.col)+(t.due?' · Hạn '+esc(t.due):' · Chưa đặt hạn')+'</small>'+bar(taskPct(t),p.color)+'</button>'+(focus?'<button type="button" class="btn" data-studio-focus="'+t.id+'" data-pid="'+p.id+'">Tập trung</button>':'')+'</article>';}
function studioSection(title,items,opts={}){return '<section class="studio-section"><h3>'+title+' <small>'+items.length+'</small></h3>'+items.map(t=>studioTaskRow(t,opts)).join('')+(!items.length?'<p class="studio-empty">Không có công việc trong nhóm này.</p>':'')+'</section>';}
function studioDashboard(){const tasks=allTasks(),day=today(),week=zenWeek(day),ranked=zenRank(tasks,day),focus=ranked.filter(t=>t.focus).slice(0,3),late=ranked.filter(t=>t.due&&t.due<day),now=ranked.filter(t=>t.due===day),upcoming=ranked.filter(t=>t.due>day&&t.due<=week.end);
 return '<section class="studio-next"><div class="studio-heading"><div><span class="eyebrow">BẮT ĐẦU TỪ ĐIỀU QUAN TRỌNG</span><h2>Việc cần làm tiếp theo</h2><p>'+esc(day)+' · Gợi ý dựa trên hạn và mức độ ưu tiên; bạn chủ động chọn kế hoạch.</p></div><div class="studio-actions"><button class="btn" data-studio="choose-focus">Chọn 3 việc</button><button class="btn" data-studio="review">Tổng kết tuần</button><button class="btn" data-studio="templates">Thư viện mẫu</button></div></div><div class="studio-dashboard-grid">'+studioSection('3 việc tập trung',focus,{focus:true})+studioSection('Hôm nay',now,{focus:true})+studioSection('Quá hạn',late,{focus:true})+studioSection('Còn lại trong tuần',upcoming,{focus:true})+'</div><details class="studio-section"><summary>Gợi ý kế hoạch ngày / tuần</summary><p>Ưu tiên việc quá hạn, đến hạn hôm nay, rồi việc quan trọng. Chọn tối đa 3 việc cho ngày; các việc còn lại giữ trong danh sách tuần.</p>'+ranked.slice(0,7).map((t,i)=>'<div class="studio-suggestion"><span>'+(i<3?'Ngày · ':'Tuần · ')+(i+1)+'</span>'+studioTaskRow(t,{focus:true})+'</div>').join('')+'</details></section>';
}
const studioDashboardBefore=dashboard;dashboard=function(){return studioDashboard()+studioDashboardBefore();};
function studioChooseFocus(){const chosen=new Set(allTasks().filter(t=>t.focus&&t.col!=='Done').slice(0,3).map(t=>t.id));modal('<h2>Chọn tối đa 3 việc tập trung</h2><p>Danh sách này được lưu cùng tài khoản.</p><div class="studio-choices">'+zenRank(allTasks(),today()).map(t=>'<label class="check-row"><input type="checkbox" name="focus" value="'+t.id+'" '+(chosen.has(t.id)?'checked':'')+'><span>'+esc(t.title)+'<small>'+esc(t.project.name)+'</small></span></label>').join('')+'</div>',fd=>{const ids=fd.getAll('focus');if(ids.length>3)return notify('Chọn tối đa 3 việc để giữ kế hoạch vừa sức.');if(studioWrite(()=>data.projects.forEach(p=>p.tasks.forEach(t=>t.focus=ids.includes(t.id))))){$('#editor').close();render();}});}
function studioReview(){const week=zenWeek(today()),old=data.studio?.reviews?.find(r=>r.week===week.start),completed=allTasks().filter(t=>t.history?.some(h=>h.label==='Trạng thái'&&h.after==='Done'&&new Date(h.at).toLocaleDateString('en-CA',{timeZone:'Asia/Ho_Chi_Minh'})>=week.start)),late=allTasks().filter(t=>t.col!=='Done'&&t.due&&t.due<today());modal('<h2>Tổng kết tuần '+week.start+' — '+week.end+'</h2><p>1. Nhìn lại → 2. Gỡ vướng → 3. Chọn việc tuần tới</p><p>'+completed.length+' việc có lần hoàn tất trong tuần · '+late.length+' việc đang quá hạn.</p><small>Thống kê hoàn tất dựa trên lịch sử từ phiên bản 2.0; không suy đoán ngày hoàn tất của dữ liệu cũ.</small>'+studioSection('Đã hoàn tất trong tuần',completed)+['wins','blockers','plan'].map((k,i)=>'<label class="field">'+['Điều đã làm được / bài học','Việc bị vướng và cách xử lý','Kết quả muốn đạt trong tuần tới'][i]+'<textarea name="'+k+'" maxlength="4000" rows="3">'+esc(old?.[k]||'')+'</textarea></label>').join('')+'<details><summary>Các tuần đã lưu</summary>'+(data.studio?.reviews||[]).slice().reverse().map(r=>'<article class="studio-section"><strong>'+esc(r.week)+'</strong><p>'+esc(r.wins)+'</p><p>'+esc(r.blockers)+'</p><p>'+esc(r.plan)+'</p></article>').join('')+'</details>',fd=>{if(studioWrite(()=>{const z=studioMeta(),r={id:old?.id||uid(),week:week.start,at:Date.now(),wins:fd.get('wins'),blockers:fd.get('blockers'),plan:fd.get('plan')};z.reviews=[...(z.reviews||[]).filter(r=>r.week!==week.start),r].slice(-52);})){ $('#editor').close();render();notify('Đã lưu tổng kết tuần.');}});}
function studioTaskEditor(p,t,col='List'){
 if(!p)return;editing={p:p.id,t:t?.id};const original=t?JSON.stringify(t):null;let draftChecks=structuredClone(t?.checks||[]);
 const related=(data.notes||[]).filter(n=>(t?.noteIds||[]).includes(n.id)||n.projectId===p.id||(p.noteIds||[]).includes(n.id));
 const checklist=()=>draftChecks.map((c,i)=>'<div class="studio-check-edit"><input type="checkbox" name="done-'+i+'" '+(c.done?'checked':'')+' aria-label="Hoàn tất mục '+(i+1)+'"><input name="check-'+i+'" maxlength="300" required value="'+esc(c.text)+'" aria-label="Nội dung mục '+(i+1)+'"><button type="button" class="icon-btn" data-studio-remove-check="'+i+'" aria-label="Bỏ mục '+(i+1)+'">×</button></div>').join('');
 modal('<div class="studio-heading"><div><span class="eyebrow">'+esc(p.name)+'</span><h2>'+(t?'Chi tiết công việc':'Công việc mới')+'</h2></div><span class="studio-save-label" data-studio-saved role="status"></span></div><div class="studio-actions">'+(t?'<button type="button" class="btn" data-studio="focus-from-editor">Tập trung</button><button type="button" class="btn" data-studio="template-task">Lưu thành mẫu</button><button type="button" class="btn" data-studio="template-checklist">Mẫu checklist</button><button type="button" class="btn danger" data-action="delete-task">Xóa</button>':'<button type="button" class="btn" data-studio="templates">Dùng mẫu đã lưu</button>')+'</div><section class="studio-section"><h3>Nội dung chính</h3>'+(!t?'<label class="field">Dự án<select name="projectId">'+visibleProjects().map(x=>'<option value="'+x.id+'" '+(p.id===x.id?'selected':'')+'>'+esc(x.name)+'</option>').join('')+'</select></label>':'')+field('Tên công việc','title',t?.title||'','text',true,200)+'<label class="field">Mô tả<textarea name="description" maxlength="5000" rows="4">'+esc(t?.description||'')+'</textarea></label><div class="fields-row"><label class="field">Trạng thái<select name="col">'+p.columns.map(c=>'<option '+(c===(t?.col||col)?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select></label><label class="field">Mức độ<select name="priority">'+priorityOptions(t?.priority)+'</select></label></div>'+field('Nhãn','tag',t?.tag||'','text',false,40)+projectKeywordChoices(p,t)+'</section><section class="studio-section"><h3>Lịch</h3><p>Bắt đầu / kết thúc là thời gian dự kiến thực hiện. Hạn hoàn thành là cam kết riêng, không tự đổi theo ngày kết thúc. Giờ Việt Nam.</p>'+scheduleFields(t)+field('Hạn hoàn thành','due',t?.due||'','date')+'<label class="field">Lặp khi hoàn tất<select name="recurrence">'+[['','Không lặp'],['daily','Hằng ngày'],['weekly','Hằng tuần']].map(([v,l])=>'<option value="'+v+'" '+(t?.recurrence===v?'selected':'')+'>'+l+'</option>').join('')+'</select></label><small>Hoàn tất tạo một task mới cho kỳ kế tiếp, giữ mẫu nội dung và đặt lại checklist. Không tạo hàng loạt những kỳ đã bỏ lỡ.</small></section><section class="studio-section"><h3>Checklist</h3><div id="studio-checks">'+checklist()+'</div><label class="field">Thêm mục (mỗi dòng một việc)<textarea name="newChecks" maxlength="20000" rows="3"></textarea></label><label class="field">Chèn checklist mẫu<select id="studio-insert-checks"><option value="">Chọn mẫu…</option>'+(data.studio?.templates||[]).filter(x=>x.kind==='checklist').map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('')+'</select></label><div id="studio-check-progress"></div></section><section class="studio-section"><h3>Tài liệu liên quan</h3><label class="field">Liên kết ghi chú<select name="noteIds" multiple size="4" aria-describedby="studio-link-help">'+(data.notes||[]).map(n=>'<option value="'+n.id+'" '+((t?.noteIds||[]).includes(n.id)?'selected':'')+'>'+esc(n.title)+'</option>').join('')+'</select></label><small id="studio-link-help">Chọn nhiều ghi chú; trên máy tính giữ Ctrl/Cmd. Ghi chú liên kết với dự án cũng xuất hiện bên dưới.</small><div class="studio-actions">'+related.map(n=>'<button type="button" class="btn" data-studio-open-note="'+n.id+'">'+esc(n.title)+'</button>').join('')+(t?'<button type="button" class="btn" data-studio="task-files">Tệp đính kèm</button>':'')+'</div></section>'+(t?'<section class="studio-section"><h3>Bình luận nội bộ</h3><p class="studio-muted">Ghi chú nhanh trong tài khoản của bạn; không gửi thông báo cho người khác.</p><div class="studio-comments">'+(t.comments||[]).map(c=>'<article><strong>'+esc(c.author||'Bạn')+'</strong><small>'+studioStamp(c.at)+'</small><p>'+esc(c.text)+'</p><button type="button" class="text-btn" data-studio-delete-comment="'+c.id+'">Xóa bình luận</button></article>').join('')+'</div><label class="field">Bình luận mới<textarea name="comment" maxlength="2000" rows="2" placeholder="Ghi nhanh điều cần nhớ…"></textarea></label><button type="button" class="btn" data-studio="comment">Lưu và thêm bình luận</button></section><details class="studio-section"><summary>Lịch sử thay đổi · '+(t.history||[]).length+' mốc</summary><p>Giữ tối đa 80 mốc gần nhất, bắt đầu từ 2.0.0. Không có lịch sử suy diễn cho dữ liệu cũ.</p><ol class="studio-history">'+(t.history||[]).slice().reverse().map(h=>'<li><time>'+studioStamp(h.at)+'</time><strong>'+esc(h.label)+'</strong><p>'+esc(h.before)+' → '+esc(h.after)+'</p></li>').join('')+'</ol></details>':'') ,fd=>commit(fd));
 const dialog=$('#editor'),form=$('#editor-form');dialog.studioDirty=false;dialog.classList.add('studio-task-dialog');const epoch=dialog.studioEpoch;dialog.addEventListener('close',()=>{if(dialog.studioEpoch===epoch){dialog.classList.remove('studio-task-dialog');dialog.studioCommit=null;}},{once:true});
 function collectChecks(){return draftChecks.filter((c,i)=>!form.querySelector('[data-studio-remove-check="'+i+'"]')?.dataset.removed).map((c,i)=>({...c,text:form.elements['check-'+draftChecks.indexOf(c)].value.trim(),done:form.elements['done-'+draftChecks.indexOf(c)].checked}));}
 function commit(fd=new FormData(form),close=true){
  if(!form.reportValidity())return false;const dest=t?project(p.id):project(fd.get('projectId')),current=t?dest?.tasks.find(x=>x.id===t.id):null;
  if(!dest||t&&!current)return notify('Công việc hoặc dự án đã bị xóa.'),false;
  if(t&&JSON.stringify(current)!==original)return notify('Công việc vừa thay đổi. Sao chép nội dung đang sửa trước khi mở lại.'),false;
  const checks=collectChecks().concat(String(fd.get('newChecks')||'').split('\n').map(x=>x.trim()).filter(Boolean).map(text=>({id:uid(),text,done:false})));
  if(checks.some(c=>!c.text||c.text.length>300)||checks.length>200)return notify('Checklist tối đa 200 mục, mỗi mục 300 ký tự.'),false;
  const start=fd.get('start')||'',end=fd.get('end')||'';if(start&&end&&start>end)return notify('Kết thúc phải sau bắt đầu.'),false;
  let state=fd.get('col');if(!dest.columns.includes(state))state='List';if(current&&state===current.col){if(checks.length&&checks.every(c=>c.done))state='Done';else if(state==='Done'&&checks.some(c=>!c.done))state='Doing';}if(state==='Done')checks.forEach(c=>c.done=true);
  const labels=[...(t?.labels||[]).filter(l=>!(dest.keywords||[]).some(k=>k.name===l.name)),...fd.getAll('project-keyword').map(i=>dest.keywords?.[Number(i)]).filter(Boolean)];
  const value={labels,title:fd.get('title').trim(),description:fd.get('description'),tag:fd.get('tag'),col:state,priority:fd.get('priority')||'',start,end,due:fd.get('due')||'',recurrence:fd.get('recurrence')||'',checks,noteIds:fd.getAll('noteIds')};const comment=String(fd.get('comment')||'').trim();let saved;
  const ok=studioWrite(()=>{if(current){Object.assign(current,value);saved=current;}else{if(dest.tasks.length>=2000)throw Error('Dự án đã đạt giới hạn 2.000 task.');saved={id:uid(),...value};dest.tasks.push(saved);}if(comment){saved.comments||=[];if(saved.comments.length>=100)throw Error('Tối đa 100 bình luận mỗi task.');saved.comments.push({id:uid(),text:comment,author:currentUser?.name||'Bạn',at:Date.now()});}});
  if(ok){dialog.studioDirty=false;if(close)dialog.close();render();return {p:dest,t:saved};}return false;
 }
 dialog.studioCommit=()=>commit(new FormData(form),false);
 form.oninput=()=>{dialog.studioDirty=true;const label=form.querySelector('[data-studio-saved]');if(label)label.textContent='Đang chỉnh sửa · chưa lưu';const boxes=[...form.querySelectorAll('#studio-checks input[type=checkbox]:not(:disabled)')],done=boxes.filter(x=>x.checked).length;$('#studio-check-progress').innerHTML=bar(boxes.length?Math.round(done/boxes.length*100):0,p.color);};
 $('#studio-insert-checks').onchange=e=>{const tpl=data.studio?.templates?.find(x=>x.id===e.target.value);if(tpl){const v=JSON.parse(tpl.payload);form.elements.newChecks.value+=[form.elements.newChecks.value?'\n':'',...(v.checks||[]).map(c=>c.text)].join('\n');form.oninput();}};
 form.onclick=e=>{const b=e.target.closest('[data-studio-remove-check]');if(!b)return;b.dataset.removed='1';b.closest('.studio-check-edit').hidden=true;b.closest('.studio-check-edit').querySelectorAll('input').forEach(x=>x.disabled=true);form.oninput();};studioSaveLabels();
}
taskForm=studioTaskEditor;taskDetail=studioTaskEditor;
function studioFocus(p,t){Studio.elapsed=0;Studio.runningAt=0;clearInterval(Studio.timer);modal('<div class="studio-focus"><span class="eyebrow">CHẾ ĐỘ TẬP TRUNG · '+esc(p.name)+'</span><h2>'+esc(t.title)+'</h2><p class="detail-description">'+esc(t.description)+'</p>'+studioDates(t)+bar(taskPct(t),p.color)+'<div id="studio-focus-checks">'+t.checks.map(c=>'<label class="check-row"><input type="checkbox" data-studio-focus-check="'+c.id+'" '+(c.done?'checked':'')+'><span>'+esc(c.text)+'</span></label>').join('')+'</div><div class="studio-section"><h3>Ghi chú liên quan</h3>'+(data.notes||[]).filter(n=>(t.noteIds||[]).includes(n.id)||n.projectId===p.id||(p.noteIds||[]).includes(n.id)).map(n=>'<details><summary>'+esc(n.title)+'</summary><p class="studio-note-text">'+esc(n.text)+'</p><button type="button" class="btn" data-studio-open-note="'+n.id+'">Mở ghi chú / tài liệu</button></details>').join('')+'</div><details class="studio-timer"><summary>Bộ đếm thời gian (tùy chọn)</summary><output id="studio-timer">00:00</output><button type="button" class="btn" data-studio="timer">Bắt đầu / Tạm dừng</button><button type="button" class="btn" data-studio="timer-reset">Đặt lại</button><small>Chỉ đo phiên hiện tại; rời chế độ tập trung sẽ đặt lại.</small></details><label class="field">Ghi chú nhanh<textarea id="studio-focus-comment" maxlength="2000"></textarea></label><div class="studio-actions"><button type="button" class="btn" data-studio="focus-comment">Lưu ghi chú nhanh</button><button type="button" class="btn primary" data-studio="focus-done">Hoàn tất task</button><button type="button" class="btn" data-studio="focus-edit">Mở chi tiết</button></div><span data-studio-saved role="status"></span></div>',null,true);Studio.focus={pid:p.id,tid:t.id};$('#editor').classList.add('studio-focus-dialog');const epoch=$('#editor').studioEpoch;$('#editor').addEventListener('close',()=>{if($('#editor').studioEpoch===epoch){$('#editor').classList.remove('studio-focus-dialog');clearInterval(Studio.timer);Studio.focus=null;}},{once:true});studioSaveLabels();}
