function studioSaveTemplate(kind,source){modal('<h2>Lưu '+({project:'dự án',task:'task',checklist:'checklist',note:'ghi chú'}[kind])+' thành mẫu</h2>'+field('Tên mẫu','name',(source.name||source.title||'Mẫu mới').slice(0,100),'text',true,100)+'<p>Mẫu chỉ giữ cấu trúc và nội dung. Không sao chép lịch, bình luận, lịch sử, tệp riêng tư hoặc trạng thái hoàn tất.</p>',fd=>{if(studioWrite(()=>{const z=studioMeta();z.templates||=[];if(z.templates.length>=60)throw Error('Tối đa 60 mẫu; hãy xóa mẫu không dùng.');z.templates.push({id:uid(),name:fd.get('name').trim(),kind,payload:JSON.stringify(zenTemplatePayload(kind,source))});}))studioTemplates();});}
