function studioUseTemplate(id){const tpl=data.studio?.templates?.find(x=>x.id===id);if(!tpl)return;const source=JSON.parse(tpl.payload);modal('<h2>Dùng mẫu: '+esc(tpl.name)+'</h2>'+(['task','checklist'].includes(tpl.kind)?'<label class="field">Dự án đích<select name="projectId" required>'+visibleProjects().map(p=>'<option value="'+p.id+'" '+(p.id===active?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label>':'')+field('Tên mới','name',source.name||source.title||tpl.name,'text',true,tpl.kind==='project'?100:tpl.kind==='note'?150:200),fd=>{let result;if(studioWrite(()=>{if(tpl.kind==='project'){if(data.projects.length>=100)throw Error('Tối đa 100 dự án.');const p={...source,id:uid(),name:fd.get('name'),tasks:(source.tasks||[]).map(t=>zenFreshTask(t,uid)),dependencies:[]};data.projects.push(p);result={p};}else if(tpl.kind==='note'){data.notes||=[];if(data.notes.length>=500)throw Error('Tối đa 500 ghi chú.');const n={...source,id:uid(),title:fd.get('name')};data.notes.push(n);result={n};}else{const p=project(fd.get('projectId'));if(!p)throw Error('Tạo hoặc chọn dự án trước.');if(p.tasks.length>=2000)throw Error('Dự án đã đủ 2.000 task.');const t=zenFreshTask(source,uid);t.title=fd.get('name');p.tasks.push(t);result={p,t};}})){ $('#editor').close();render();if(result.n)noteForm(result.n);else if(result.t)taskDetail(result.p,result.t);else go('projects',result.p.id);}});}
