noteForm=function(n){studioNoteBefore(n);if(typeof contentReadOnly!=='undefined'&&contentReadOnly)return;const panel=document.createElement('section');panel.className='studio-note-links';panel.innerHTML='<h3>Liên kết công việc</h3><label class="field">Dự án liên quan<select id="studio-note-project"><option value="">Không liên kết</option>'+visibleProjects().map(p=>'<option value="'+p.id+'" '+(n?.projectId===p.id?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label><div class="studio-actions"><button type="button" class="btn" data-studio="note-to-task">Tạo task từ ghi chú</button><button type="button" class="btn" data-studio="template-note">Lưu thành mẫu</button></div><div>'+allTasks().filter(t=>(t.noteIds||[]).includes(n?.id)).map(t=>'<button type="button" class="text-btn" data-studio-linked-task="'+t.id+'" data-pid="'+t.project.id+'">'+esc(t.project.name)+' / '+esc(t.title)+'</button>').join('')+'</div>';$('#editor-body').append(panel);const commit=$('#editor').noteCommit;if(commit)$('#editor').noteCommit=function(){const ok=commit();if(!ok)return ok;const note=data.notes?.find(x=>x.id===$('#editor').dataset.noteId),pid=$('#studio-note-project')?.value||'';if(note&&note.projectId!==pid)return studioWrite(()=>note.projectId=pid);return true;};$('#studio-note-project').onchange=()=>$('#editor').noteCommit?.();};
