tasksPage=function(){return heading('CÔNG VIỆC','Danh sách công việc','Bộ lọc và mẫu được lưu cùng tài khoản.','<button class="btn primary" data-global-task>+ Công việc mới</button>')+'<div class="studio-filters">'+workFilters()+'<label>Trạng thái<select id="filter-status"><option value="">Tất cả</option>'+[...new Set(data.projects.flatMap(p=>p.columns))].map(c=>'<option '+(filterStatus===c?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select></label><label>Mức độ<select id="filter-priority">'+priorityOptions(filterPriority)+'</select></label><label>Sắp xếp<select id="studio-sort">'+[['due','Hạn gần nhất'],['title','Tên A–Z'],['priority','Mức độ'],['progress','Tiến độ giảm dần']].map(([v,l])=>'<option value="'+v+'" '+(Studio.sort===v?'selected':'')+'>'+l+'</option>').join('')+'</select></label><label>Bộ lọc đã lưu<select id="studio-filter"><option value="">Chọn bộ lọc…</option>'+(data.studio?.filters||[]).map(f=>'<option value="'+f.id+'">'+esc(f.name)+'</option>').join('')+'</select></label><button class="btn" data-studio="save-filter">Lưu bộ lọc</button><button class="btn" data-studio="manage-filters">Quản lý bộ lọc</button><button class="btn" data-studio="clear-filters">Bỏ lọc</button></div><div class="studio-bulk"><label><input type="checkbox" id="studio-select-all" '+(studioFiltered().length&&studioFiltered().every(t=>Studio.picked.has(t.id))?'checked':'')+'> Chọn tất cả kết quả</label><span>'+Studio.picked.size+' đã chọn</span><button class="btn" data-studio="bulk">Cập nhật nhiều task</button></div><div class="studio-list">'+studioFiltered().map(t=>studioTaskRow(t,{select:true})).join('')+'</div>';};
