function studioBulk(){const tasks=allTasks().filter(t=>Studio.picked.has(t.id));if(!tasks.length)return notify('Chọn ít nhất một task.');const columns=tasks[0].project.columns.filter(c=>tasks.every(t=>t.project.columns.includes(c)));modal('<h2>Cập nhật '+tasks.length+' công việc</h2><p>Chỉ áp dụng các trường được chọn. Các thay đổi sẽ xuất hiện trong lịch sử từng task.</p><label class="field">Trạng thái<select name="col"><option value="">Giữ nguyên</option>'+columns.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select></label><label class="field">Mức độ<select name="priority"><option value="keep">Giữ nguyên</option>'+priorityOptions('')+'</select></label><label class="check-row"><input type="checkbox" name="setDue"> Đổi / xóa hạn hoàn thành</label>'+field('Hạn mới (trống để xóa)','due','','date'),fd=>{if(studioWrite(()=>{for(const p of data.projects)for(const t of p.tasks)if(Studio.picked.has(t.id)){if(fd.get('col')){t.col=fd.get('col');if(t.col==='Done')t.checks.forEach(c=>c.done=true);else if(t.checks.length&&t.checks.every(c=>c.done))t.checks.at(-1).done=false;}if(fd.get('priority')!=='keep')t.priority=fd.get('priority');if(fd.has('setDue'))t.due=fd.get('due');}})){Studio.picked.clear();$('#editor').close();render();}});}
